	for i := uint8(0); i < q.nt; i++ {
		t := q.toks[i]
		if t.Kind() != runtime.KLeaf {
			continue
		}
		switch runtime.Op(t.Op()) {
		case opIsNull, opIsNotNull:
			continue
		case opIn:
			if q.anyRaw != nil {
				b.anyRaw = q.anyRaw
				v = append(v, &b.anyRaw)
			} else {
				b.anyStr = q.anyStr
				v = append(v, &b.anyStr)
			}
			continue
		}
		switch t.Col() {
		case 0:
			b.raws[nr] = q.raws[nr]
			v = append(v, &b.raws[nr])
			nr++
		case 1:
			b.raws[nr] = q.raws[nr]
			v = append(v, &b.raws[nr])
			nr++
		case 2:
			b.strs[ns] = q.strs[ns]
			v = append(v, &b.strs[ns])
			ns++
		case 3:
			b.strs[ns] = q.strs[ns]
			v = append(v, &b.strs[ns])
			ns++
		case 4:
			b.nums[nn] = q.nums[nn]
			v = append(v, &b.nums[nn])
			nn++
		case 5:
			b.strs[ns] = q.strs[ns]
			v = append(v, &b.strs[ns])
			ns++
		case 6:
			b.tims[ntm] = q.tims[ntm]
			v = append(v, &b.tims[ntm])
			ntm++
		case 7:
			b.tims[ntm] = q.tims[ntm]
			v = append(v, &b.tims[ntm])
			ntm++
		}
	}
	b.limit = q.limit
	v = append(v, &b.limit)
	b.vals = v
